import { types } from "node:util";
import type { SecretBodyCause } from "./damage";
export const NOBLE_SECRET_BODY_POLICY = "awa_noble_secret_body_v1" as const;
export type NobleWolfPolicy = "standard" | "no_blast_no_self_knife";
export type BodyRepeatPolicy = "awa_nonconsecutive_nights_v1" | "awa_repeat_v1";
export interface NightChoice {
  day: number;
  targetId: number | null;
}
export type BodyResource =
  | { kind: "intact" }
  | { kind: "night_spent"; day: number; targetId: number; cause: SecretBodyCause }
  | { kind: "exile_revealed"; day: number };
export interface SecretBodyState {
  policy: typeof NOBLE_SECRET_BODY_POLICY;
  protectionRepeatPolicy: BodyRepeatPolicy;
  lastChoice: NightChoice | null;
  body: BodyResource;
}
export interface ServantContract {
  id: string;
  targetId: number;
  createdNight: number;
  expiresNight: number;
  status: { kind: "pending" } | { kind: "cleared" | "expired" | "target_dead"; day: number };
}
export interface NobleState {
  policy: typeof NOBLE_SECRET_BODY_POLICY;
  wolfActionPolicy: NobleWolfPolicy;
  lastChoice: NightChoice | null;
  contracts: ServantContract[];
}
function positive(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER - 1
  );
}
function data(value: unknown, keys: readonly string[]): Record<string, unknown> | undefined {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value)) return;
  const proto = Object.getPrototypeOf(value);
  if (proto !== Object.prototype && proto !== null) return;
  const fields = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(fields).length !== keys.length) return;
  const result: Record<string, unknown> = {};
  for (const key of keys) {
    const field = fields[key];
    if (!field || !("value" in field)) return;
    result[key] = field.value;
  }
  return result;
}
function dense(value: unknown): unknown[] | undefined {
  if (
    types.isProxy(value) ||
    !Array.isArray(value) ||
    Object.getPrototypeOf(value) !== Array.prototype
  )
    return;
  const fields: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      value as object,
    ),
    length: unknown = fields.length?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(fields).length !== length + 1
  )
    return;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const field = fields[String(i)];
    if (!field || !("value" in field)) return;
    result.push(field.value);
  }
  return result;
}
function livingSnapshot(value: unknown): number[] {
  const ids = dense(value);
  if (!ids || ids.some((id) => !positive(id)) || new Set(ids).size !== ids.length)
    throw Error("noble_secret_body_roster_invalid");
  return ids as number[];
}
function choice(value: unknown): NightChoice | null | undefined {
  if (value === null) return null;
  const row = data(value, ["day", "targetId"]);
  if (!row || !positive(row.day) || (row.targetId !== null && !positive(row.targetId))) return;
  return { day: row.day, targetId: row.targetId as number | null };
}
export function createSecretBodyState(
  policy: BodyRepeatPolicy = "awa_nonconsecutive_nights_v1",
): SecretBodyState {
  if (policy !== "awa_nonconsecutive_nights_v1" && policy !== "awa_repeat_v1")
    throw Error("secret_body_policy_invalid");
  return {
    policy: NOBLE_SECRET_BODY_POLICY,
    protectionRepeatPolicy: policy,
    lastChoice: null,
    body: { kind: "intact" },
  };
}
export function readSecretBodyState(value: unknown): SecretBodyState | undefined {
  const row = data(value, ["policy", "protectionRepeatPolicy", "lastChoice", "body"]);
  if (
    !row ||
    row.policy !== NOBLE_SECRET_BODY_POLICY ||
    !["awa_nonconsecutive_nights_v1", "awa_repeat_v1"].includes(
      row.protectionRepeatPolicy as string,
    )
  )
    return;
  const last = choice(row.lastChoice);
  if (last === undefined) return;
  let body: BodyResource | undefined;
  const intact = data(row.body, ["kind"]);
  if (intact?.kind === "intact") body = { kind: "intact" };
  const night = data(row.body, ["kind", "day", "targetId", "cause"]);
  if (
    night?.kind === "night_spent" &&
    positive(night.day) &&
    positive(night.targetId) &&
    ["wolf_kill", "poison", "demon_hunt", "demon_hunt_backlash", "servant_expiry"].includes(
      night.cause as string,
    ) &&
    last?.day === night.day
  )
    body = {
      kind: "night_spent",
      day: night.day,
      targetId: night.targetId,
      cause: night.cause as SecretBodyCause,
    };
  const exile = data(row.body, ["kind", "day"]);
  if (exile?.kind === "exile_revealed" && positive(exile.day) && (!last || last.day <= exile.day))
    body = { kind: "exile_revealed", day: exile.day };
  if (!body) return;
  return {
    policy: NOBLE_SECRET_BODY_POLICY,
    protectionRepeatPolicy: row.protectionRepeatPolicy as BodyRepeatPolicy,
    lastChoice: last,
    body,
  };
}
export function chooseBodyTarget(
  raw: SecretBodyState,
  day: number,
  targetId: number | null,
  livingIds: readonly number[],
): SecretBodyState {
  const state = readSecretBodyState(raw),
    living = livingSnapshot(livingIds);
  if (
    !state ||
    state.body.kind !== "intact" ||
    !positive(day) ||
    (state.lastChoice && state.lastChoice.day >= day)
  )
    throw Error("secret_body_unavailable");
  if (
    targetId !== null &&
    (!positive(targetId) ||
      !living.includes(targetId) ||
      (state.protectionRepeatPolicy === "awa_nonconsecutive_nights_v1" &&
        state.lastChoice?.day === day - 1 &&
        state.lastChoice.targetId === targetId))
  )
    throw Error("secret_body_target");
  return { ...state, lastChoice: { day, targetId } };
}
/** Caller owns original-life authorization and synchronously pairs this consumption with the FINAL block. */
export function spendBodyForNight(
  raw: SecretBodyState,
  day: number,
  actorId: number,
  block: { targetId: number; cause: SecretBodyCause },
): SecretBodyState {
  const state = readSecretBodyState(raw);
  if (
    !state ||
    state.body.kind !== "intact" ||
    !positive(day) ||
    !positive(actorId) ||
    state.lastChoice?.day !== day
  )
    throw Error("secret_body_unavailable");
  const proposed = data(block, ["targetId", "cause"]);
  if (
    !proposed ||
    !positive(proposed.targetId) ||
    !["wolf_kill", "poison", "demon_hunt", "demon_hunt_backlash", "servant_expiry"].includes(
      proposed.cause as string,
    ) ||
    (proposed.targetId !== actorId && proposed.targetId !== state.lastChoice.targetId)
  )
    throw Error("secret_body_block_invalid");
  return {
    ...state,
    body: {
      kind: "night_spent",
      day,
      targetId: proposed.targetId,
      cause: proposed.cause as SecretBodyCause,
    },
  };
}
export function revealBodyByExile(raw: SecretBodyState, day: number): SecretBodyState {
  const state = readSecretBodyState(raw);
  if (
    !state ||
    state.body.kind !== "intact" ||
    !positive(day) ||
    (state.lastChoice && state.lastChoice.day > day)
  )
    throw Error("secret_body_unavailable");
  return { ...state, body: { kind: "exile_revealed", day } };
}
export function createNobleState(policy: NobleWolfPolicy = "standard"): NobleState {
  if (policy !== "standard" && policy !== "no_blast_no_self_knife")
    throw Error("night_noble_policy_invalid");
  return {
    policy: NOBLE_SECRET_BODY_POLICY,
    wolfActionPolicy: policy,
    lastChoice: null,
    contracts: [],
  };
}
export function readNobleState(value: unknown): NobleState | undefined {
  const row = data(value, ["policy", "wolfActionPolicy", "lastChoice", "contracts"]);
  if (
    !row ||
    row.policy !== NOBLE_SECRET_BODY_POLICY ||
    !["standard", "no_blast_no_self_knife"].includes(row.wolfActionPolicy as string)
  )
    return;
  const last = choice(row.lastChoice),
    rows = dense(row.contracts);
  if (last === undefined || !rows || (last && last.day < 2)) return;
  const contracts: ServantContract[] = [];
  for (const raw of rows) {
    const contract = data(raw, ["id", "targetId", "createdNight", "expiresNight", "status"]);
    if (
      !contract ||
      !positive(contract.targetId) ||
      !positive(contract.createdNight) ||
      contract.createdNight < 2 ||
      contract.id !== `servant:night:${contract.createdNight}` ||
      contract.expiresNight !== contract.createdNight + 1
    )
      return;
    const previous = contracts.at(-1);
    if (
      previous &&
      (previous.status.kind === "pending" || contract.createdNight <= previous.status.day)
    )
      return;
    let status: ServantContract["status"] | undefined;
    if (data(contract.status, ["kind"])?.kind === "pending") status = { kind: "pending" };
    const ended = data(contract.status, ["kind", "day"]);
    if (
      ended &&
      ["cleared", "expired", "target_dead"].includes(ended.kind as string) &&
      positive(ended.day) &&
      ended.day >= contract.createdNight &&
      ended.day <= Number(contract.expiresNight) &&
      (ended.kind !== "expired" || ended.day === contract.expiresNight)
    )
      status = { kind: ended.kind as "cleared" | "expired" | "target_dead", day: ended.day };
    if (!status) return;
    contracts.push({
      id: contract.id as string,
      targetId: contract.targetId,
      createdNight: contract.createdNight,
      expiresNight: Number(contract.expiresNight),
      status,
    });
  }
  const latest = contracts.at(-1);
  if (
    latest &&
    (!last ||
      last.day < latest.createdNight ||
      (last.day === latest.createdNight && last.targetId !== latest.targetId) ||
      (last.day > latest.createdNight &&
        (last.targetId !== null ||
          latest.status.kind === "pending" ||
          last.day <= latest.status.day)) ||
      (latest.status.kind === "pending" && last.day !== latest.createdNight))
  )
    return;
  if (!latest && last?.targetId !== null && last !== null) return;
  return {
    policy: NOBLE_SECRET_BODY_POLICY,
    wolfActionPolicy: row.wolfActionPolicy as NobleWolfPolicy,
    lastChoice: last,
    contracts,
  };
}
export function chooseServant(
  raw: NobleState,
  day: number,
  targetId: number | null,
  actorId: number,
  livingIds: readonly number[],
): NobleState {
  const state = readNobleState(raw),
    living = livingSnapshot(livingIds),
    latest = state?.contracts.at(-1);
  if (
    !state ||
    !positive(day) ||
    day < 2 ||
    !positive(actorId) ||
    (state.lastChoice && state.lastChoice.day >= day) ||
    state.contracts.some((c) => c.status.kind === "pending") ||
    (latest && latest.status.kind !== "pending" && day <= latest.status.day)
  )
    throw Error("night_noble_unavailable");
  if (
    targetId !== null &&
    (!positive(targetId) || targetId === actorId || !living.includes(targetId))
  )
    throw Error("night_noble_target");
  return {
    ...state,
    lastChoice: { day, targetId },
    contracts:
      targetId === null
        ? state.contracts
        : [
            ...state.contracts,
            {
              id: `servant:night:${day}`,
              targetId,
              createdNight: day,
              expiresNight: day + 1,
              status: { kind: "pending" },
            },
          ],
  };
}
/** One terminal transition. Original owner/target-life checks and expiry source commit belong to the controller. */
export function endServant(
  raw: NobleState,
  id: string,
  day: number,
  kind: "cleared" | "expired" | "target_dead",
): NobleState {
  const state = readNobleState(raw),
    contract = state?.contracts.find((c) => c.id === id);
  if (
    !state ||
    !contract ||
    contract.status.kind !== "pending" ||
    !positive(day) ||
    day < contract.createdNight ||
    day > contract.expiresNight ||
    !["cleared", "expired", "target_dead"].includes(kind) ||
    (kind === "expired" && day !== contract.expiresNight)
  )
    throw Error("night_noble_contract_unavailable");
  return {
    ...state,
    contracts: state.contracts.map((c) => (c.id === id ? { ...c, status: { kind, day } } : c)),
  };
}

/**
 * 负责贵族／夜仆资源、原生命与契约权威。输入为原 roster、实际夜间及受控行动；
 * 输出为已重检提交、通知、到期提案与显式纯数据快照。单一 owner 持有原实例和付款状态。
 * 正常／撤销、原体替换、资源与记录失败保留原合法前缀，不恢复已付契约或修改对局阶段。
 * 新夜间身份仅关联本 Night 对象；到期消费同一身份，不改变旧日次数值、期限或归档字段。
 * 规则依据：docs/rules/awa-noble-secret-body-twelve-v1.md。
 */
import { attachNightUnit, isNightUnit, nightUnitOf, type NightUnit } from "../../../../core/domain/night-unit";
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { World } from "../../../../core/domain/world";
import { Camp, Role, Phase } from "../../../../core/domain/identity";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import {
  readNobleState,
  readSecretBodyState,
  chooseServant,
  chooseBodyTarget,
  endServant,
  spendBodyForNight,
  revealBodyByExile,
  type NobleState,
  type SecretBodyState,
} from "./state";
import { planSecretBodyBlock, copySecretBodySources, type SecretBodySources } from "./damage";
import {
  copyNobleKnowledge,
  copySecretBodyKnowledge,
  projectNobleKnowledge,
  projectSecretBodyKnowledge,
} from "./player_projection";
import type {
  NobleKnowledge,
  SecretBodyKnowledge,
  NobleBodyNightNotice,
} from "@ai-werewolf-arena/game-contract/facts/noble-secret-body";
const invalid = Symbol("invalid_noble_body_owner");
function own(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return invalid;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : field ? invalid : undefined;
}
const identityKeys = ["id", "seat", "name", "sessionId"] as const;
interface OriginalPlayer {
  readonly id: number;
  readonly role: RoleComponent;
  readonly kind: unknown;
  readonly camp: unknown;
  readonly privateState: Record<string, unknown>;
  readonly identity: unknown;
  readonly identityValues: readonly unknown[];
  readonly campComponent: unknown;
  readonly victory: unknown;
  readonly victoryValues: string;
  readonly life: AliveComponent;
  readonly version: number;
}
function factoryLife(life: AliveComponent): boolean {
  if (types.isProxy(life)) return false;
  const original = aliveLifeDescriptor(life),
    current = Object.getOwnPropertyDescriptor(life, "alive");
  return (
    !!original &&
    !!current &&
    original.get === current.get &&
    original.set === current.set &&
    original.enumerable === current.enumerable &&
    original.configurable === current.configurable
  );
}
function victoryJson(value: unknown): string | null {
  const affiliations = own(value, "affiliations");
  if (types.isProxy(affiliations) || !Array.isArray(affiliations)) return null;
  const fields: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      affiliations as object,
    ),
    length: unknown = fields.length?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(fields).length !== length + 1
  )
    return null;
  const entries: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const field = fields[String(i)];
    if (!field || !("value" in field)) return null;
    const raw = field.value;
    if (!raw || typeof raw !== "object" || types.isProxy(raw) || Array.isArray(raw)) return null;
    const row = Object.getOwnPropertyDescriptors(raw),
      data: Record<string, unknown> = {};
    for (const key of Reflect.ownKeys(row)) {
      if (
        typeof key !== "string" ||
        !("value" in row[key]!) ||
        !["string", "number"].includes(typeof row[key]!.value)
      )
        return null;
      data[key] = row[key]!.value;
    }
    entries.push(data);
  }
  return JSON.stringify(entries);
}
function capture(world: World, id: number): OriginalPlayer {
  const role = world.getComponent(id, COMPONENT.Role),
    life = world.getComponent(id, COMPONENT.Alive),
    identity = world.getComponent(id, COMPONENT.Identity),
    victory = world.getComponent(id, COMPONENT.Victory);
  const privateState = own(role, "privateState"),
    kind = own(role, "role"),
    camp = own(role, "camp"),
    campComponent = world.getComponent(id, COMPONENT.Camp),
    identityValues = identityKeys.map((k) => own(identity, k)),
    victoryValues = victoryJson(victory);
  const [identityId, seat, name, sessionId] = identityValues;
  if (
    !role ||
    !Object.values(Role).includes(kind as Role) ||
    ![Camp.Good, Camp.Wolf].includes(camp as Camp) ||
    own(campComponent, "camp") !== camp ||
    identityId !== id ||
    !Number.isSafeInteger(seat) ||
    (seat as number) < 1 ||
    typeof name !== "string" ||
    !name.trim() ||
    typeof sessionId !== "string" ||
    !sessionId.trim() ||
    !life ||
    !factoryLife(life) ||
    !life.alive ||
    aliveLifeVersion(life) === undefined ||
    !privateState ||
    typeof privateState !== "object" ||
    types.isProxy(privateState) ||
    Array.isArray(privateState) ||
    victoryValues === null ||
    victoryValues !== JSON.stringify([{ kind: "faction", faction: camp }])
  )
    throw Error("noble_body_initial_binding_invalid");
  return {
    id,
    role,
    kind,
    camp,
    privateState: privateState as Record<string, unknown>,
    identity,
    identityValues,
    campComponent,
    victory,
    victoryValues,
    life,
    version: aliveLifeVersion(life)!,
  };
}
function playerCurrent(world: World, p: OriginalPlayer, living = false): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    own(p.role, "role") !== p.kind ||
    own(p.role, "camp") !== p.camp ||
    own(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    identityKeys.some((k, i) => own(p.identity, k) !== p.identityValues[i]) ||
    world.getComponent(p.id, COMPONENT.Camp) !== p.campComponent ||
    own(p.campComponent, "camp") !== p.camp ||
    world.getComponent(p.id, COMPONENT.Victory) !== p.victory ||
    victoryJson(p.victory) !== p.victoryValues ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life ||
    !factoryLife(p.life)
  )
    return false;
  const version = aliveLifeVersion(p.life);
  return p.life.alive ? version === p.version : !living && version === p.version + 1;
}
interface ContractBinding {
  readonly target: OriginalPlayer;
  readonly createdNight: number;
  readonly expiresNight: number;
  readonly id: string;
}
interface ChoiceLease {
  opened: boolean;
  committed: boolean;
}
interface Night {
  readonly day: number;
  readonly isCurrent: () => boolean;
  status: "open" | "normal" | "aborted";
  readonly body: ChoiceLease;
  readonly noble: ChoiceLease;
  readonly requiresBody: boolean;
  readonly requiresNoble: boolean;
  bodyTarget: OriginalPlayer | null;
  bodyResolved: boolean;
  expiryProcessed: boolean;
  revealOpened: boolean;
  revealCompleted: boolean;
}
interface Owner {
  readonly world: World;
  readonly players: ReadonlyMap<number, OriginalPlayer>;
  readonly noble: OriginalPlayer;
  readonly body: OriginalPlayer;
  readonly nobleState: NobleState;
  readonly bodyState: SecretBodyState;
  nobleJson: string;
  bodyJson: string;
  readonly contracts: Map<string, ContractBinding>;
  readonly nights: Map<number, Night>;
  active: Night | null;
  checkingController: boolean;
  nobleKnowledge: NobleKnowledge;
  bodyKnowledge: SecretBodyKnowledge;
  readonly notices: NobleBodyNightNotice[];
}
const owners = new WeakMap<World, Owner>();
function canonicalState(owner: Owner): boolean {
  return (
    own(owner.noble.privateState, "noble") === owner.nobleState &&
    own(owner.body.privateState, "secretBody") === owner.bodyState &&
    JSON.stringify(readNobleState(owner.nobleState)) === owner.nobleJson &&
    JSON.stringify(readSecretBodyState(owner.bodyState)) === owner.bodyJson
  );
}
function requireOwner(world: World): Owner {
  const owner = owners.get(world);
  if (
    !owner ||
    owner.checkingController ||
    world.entityIds().length !== owner.players.size ||
    [...owner.players.values()].some((p) => !playerCurrent(world, p)) ||
    !canonicalState(owner)
  )
    throw Error("noble_body_owner_revoked");
  return owner;
}
function checkController(owner: Owner, isCurrent: () => boolean): boolean {
  if (owner.checkingController) throw Error("noble_body_controller_reentry");
  owner.checkingController = true;
  try {
    return isCurrent();
  } finally {
    owner.checkingController = false;
  }
}
function requireNight(
  world: World,
  day: number,
  allowNormal = false,
): { owner: Owner; night: Night } {
  const owner = requireOwner(world),
    night = owner.nights.get(day);
  if (
    !night ||
    (night.status !== "open" && !(allowNormal && night.status === "normal")) ||
    !checkController(owner, night.isCurrent)
  )
    throw Error("noble_body_night_unavailable");
  // The controller callback may synchronously cancel or change the owner.
  requireOwner(world);
  if (night.status !== "open" && !(allowNormal && night.status === "normal"))
    throw Error("noble_body_night_unavailable");
  return { owner, night };
}
function writeState<T extends NobleState | SecretBodyState>(current: T, next: T): void {
  const keys = Reflect.ownKeys(current),
    descriptors = Object.getOwnPropertyDescriptors(current);
  if (
    Object.getPrototypeOf(current) !== Object.prototype ||
    keys.some(
      (k) =>
        typeof k !== "string" ||
        !("value" in descriptors[k]!) ||
        descriptors[k]!.writable !== true ||
        descriptors[k]!.configurable !== true,
    ) ||
    keys.length !== Object.keys(next).length
  )
    throw Error("noble_body_state_write_revoked");
  for (const key of keys as Array<keyof T>)
    Object.defineProperty(current, key, { ...descriptors[key as string]!, value: next[key] });
}
function commitNoble(owner: Owner, next: NobleState): void {
  writeState(owner.nobleState, next);
  owner.nobleJson = JSON.stringify(next);
}
function commitBody(owner: Owner, next: SecretBodyState): void {
  writeState(owner.bodyState, next);
  owner.bodyJson = JSON.stringify(next);
}
/** Exact role/preset qualification is the bootstrap caller's responsibility. This captures
 * original native state objects once; it never initializes or grants replacement resources. */
export function installNobleBodyAuthority(world: World, nobleId: number, bodyId: number): void {
  if (owners.has(world)) throw Error("noble_body_already_installed");
  const players = new Map(world.entityIds().map((id) => [id, capture(world, id)])),
    noble = players.get(nobleId),
    body = players.get(bodyId);
  const nobleState = noble && own(noble.privateState, "noble"),
    bodyState = body && own(body.privateState, "secretBody"),
    nobleData = readNobleState(nobleState),
    bodyData = readSecretBodyState(bodyState);
  if (
    !noble ||
    !body ||
    noble === body ||
    noble.camp !== Camp.Wolf ||
    body.camp !== Camp.Good ||
    !nobleData ||
    nobleData.contracts.length ||
    nobleData.lastChoice !== null ||
    !bodyData ||
    bodyData.body.kind !== "intact" ||
    bodyData.lastChoice !== null
  )
    throw Error("noble_body_initial_state_invalid");
  owners.set(world, {
    world,
    players,
    noble,
    body,
    nobleState: nobleState as NobleState,
    bodyState: bodyState as SecretBodyState,
    nobleJson: JSON.stringify(nobleData),
    bodyJson: JSON.stringify(bodyData),
    contracts: new Map(),
    nights: new Map(),
    active: null,
    checkingController: false,
    nobleKnowledge: copyNobleKnowledge({
      wolfActionPolicy: nobleData.wolfActionPolicy,
      lastNotifiedNight: 0,
      lastChoice: null,
      contracts: [],
    }),
    bodyKnowledge: copySecretBodyKnowledge({
      protectionRepeatPolicy: bodyData.protectionRepeatPolicy,
      lastNotifiedNight: 0,
      lastChoice: null,
      resource: "intact",
      publicRevealDay: null,
