export function nobleBodyChoiceActor(
  world: World,
  day: number,
  kind: "body" | "noble",
): number | null {
  const { owner, night } = requireNight(world, day);
  const lease = night[kind];
  return (kind === "body" ? night.requiresBody : night.requiresNoble) &&
    !lease.opened &&
    !lease.committed &&
    playerCurrent(world, owner[kind], true)
    ? owner[kind].id
    : null;
