import { types } from "node:util";
/** Finite AWA Noble board only. Input is the FINAL valid sources after rescue,
 * native toxin immunity and hunt/servant clearing; this function owns no resource. */
export const SECRET_BODY_CAUSE_ORDER = Object.freeze([
  "wolf_kill",
  "poison",
  "demon_hunt",
  "demon_hunt_backlash",
  "servant_expiry",
] as const);
export type SecretBodyCause = (typeof SECRET_BODY_CAUSE_ORDER)[number];
export type SecretBodySources = Readonly<Record<string, readonly SecretBodyCause[]>>;
function playerId(value: number): boolean {
  return Number.isSafeInteger(value) && value > 0 && value < Number.MAX_SAFE_INTEGER;
}
function snapshotSources(sources: SecretBodySources): Record<string, SecretBodyCause[]> {
  const copied: Record<string, SecretBodyCause[]> = {};
  if (
    !sources ||
    typeof sources !== "object" ||
    types.isProxy(sources) ||
    Array.isArray(sources) ||
    ![Object.prototype, null].includes(Object.getPrototypeOf(sources))
  )
    throw new Error("secret_body_sources_invalid");
  const fields = Object.getOwnPropertyDescriptors(sources);
  for (const key of Reflect.ownKeys(fields)) {
    const field = typeof key === "string" ? fields[key] : undefined;
    if (
      !field ||
      !("value" in field) ||
      typeof key !== "string" ||
      !playerId(Number(key)) ||
      String(Number(key)) !== key
    )
      throw new Error("secret_body_sources_invalid");
    const raw: unknown = field.value;
    if (types.isProxy(raw) || !Array.isArray(raw) || Object.getPrototypeOf(raw) !== Array.prototype)
      throw new Error("secret_body_sources_invalid");
    const items: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      raw as object,
    );
    const length: unknown = items.length?.value;
    if (
      typeof length !== "number" ||
      !Number.isSafeInteger(length) ||
      length < 0 ||
      Reflect.ownKeys(items).length !== length + 1
    )
      throw new Error("secret_body_sources_invalid");
    const causes: SecretBodyCause[] = [];
    for (let index = 0; index < length; index++) {
      const item = items[String(index)];
      if (
        !item ||
        !("value" in item) ||
        !SECRET_BODY_CAUSE_ORDER.includes(item.value) ||
        causes.includes(item.value)
      )
        throw new Error("secret_body_sources_invalid");
      causes.push(item.value);
    }
    if (causes.length) copied[key] = causes;
  }
  return copied;
}
/** Preserve all validated finite sources when there is no paid protection. */
export function copySecretBodySources(sources: SecretBodySources): SecretBodySources {
  const copied = snapshotSources(sources);
  return Object.freeze(
    Object.fromEntries(Object.entries(copied).map(([key, value]) => [key, Object.freeze(value)])),
  );
}
export function planSecretBodyBlock(
  actorId: number,
  selectedId: number | null,
  sources: SecretBodySources,
): Readonly<{
  blocked: Readonly<{ targetId: number; cause: SecretBodyCause }> | null;
  sources: SecretBodySources;
}> {
  if (!playerId(actorId) || (selectedId !== null && !playerId(selectedId)))
    throw new Error("secret_body_target_invalid");
  const copied = snapshotSources(sources);
  const preferred = selectedId ?? actorId;
  const targetId = copied[String(preferred)]?.length ? preferred : actorId;
  const causes = copied[String(targetId)] ?? [];
  const cause = SECRET_BODY_CAUSE_ORDER.find((c) => causes.includes(c));
  if (cause) {
    copied[String(targetId)] = causes.filter((c) => c !== cause);
    if (!copied[String(targetId)]!.length) delete copied[String(targetId)];
  }
  return Object.freeze({
    blocked: cause ? Object.freeze({ targetId, cause }) : null,
    sources: Object.freeze(
      Object.fromEntries(Object.entries(copied).map(([key, value]) => [key, Object.freeze(value)])),
    ),
  });
}

/**
 * 负责从夜之贵族／觉醒愚者秘密之身的已知知识构造冻结玩家视图，结构类型直接来自契约包。
 * 输入为 known journal 与公开 phase；输出为复制的选择／契约／资源字段和 awaitingNightReport。
 * 日志所有者仍拥有知识更新；此模块仅投影，不付款或授予行动权限。标记取公开阶段
 * 与已知公开放逐状态，不能比较真实与已知库存来泄漏尚未通知的变化。
 */
import { Phase } from "../../../../core/domain/identity";
import type { NightChoice } from "./state";

import type {
  SecretBodyKnowledge,
  NobleKnowledge,
  SecretBodyPlayerState,
  NoblePlayerState,
} from "@ai-werewolf-arena/game-contract/facts/noble-secret-body";

function copyChoice(choice: NightChoice | null): NightChoice | null {
  return choice && Object.freeze({ day: choice.day, targetId: choice.targetId });
}
export function copyNobleKnowledge(known: NobleKnowledge): NobleKnowledge {
  return Object.freeze({
    wolfActionPolicy: known.wolfActionPolicy,
    lastNotifiedNight: known.lastNotifiedNight,
    lastChoice: copyChoice(known.lastChoice),
    contracts: Object.freeze(
      known.contracts.map((c) =>
        Object.freeze({
          id: c.id,
          targetId: c.targetId,
          createdNight: c.createdNight,
          expiresNight: c.expiresNight,
          status: Object.freeze({ ...c.status }),
        }),
      ),
    ),
  });
}
export function copySecretBodyKnowledge(known: SecretBodyKnowledge): SecretBodyKnowledge {
  return Object.freeze({
    protectionRepeatPolicy: known.protectionRepeatPolicy,
    lastNotifiedNight: known.lastNotifiedNight,
    resource: known.resource,
    publicRevealDay: known.publicRevealDay,
    lastChoice: copyChoice(known.lastChoice),
  });
}
export function projectSecretBodyKnowledge(
  known: SecretBodyKnowledge,
  phase: Phase,
): SecretBodyPlayerState {
  return Object.freeze({
    ...copySecretBodyKnowledge(known),
    // 按公开阶段及已知公开放逐状态决定此标记，不能用真实／已知库存差异推断尚未通知的结果。
    awaitingNightReport: phase !== Phase.Night && known.resource !== "exile_revealed",
  });
}
export function projectNobleKnowledge(known: NobleKnowledge, phase: Phase): NoblePlayerState {
  return Object.freeze({
    ...copyNobleKnowledge(known),
    awaitingNightReport: phase !== Phase.Night,
  });
}

/**
 * 负责三种强权威 checkpoint 贡献与对应原结构契约。输入为真实 World、完整／失败模式和已记录游标；
 * 输出按动物、双生、贵族、录制计数的原顺序形成数据，保留重复权威查询与 schema.parse 的失败前缀。
 * 动物最初审计快照在 setup 查询前取得；本模块不重新推导规则、不改变资源或独立 verifier。
 */
import type { World } from "../../core/domain/world";
import type { RecordedCheckpoint } from "../reproduction";
import { animalCheckpointSchema } from "../animal_dream_checkpoint";
import { fragrantCheckpointSchema } from "../fragrant_pair_seer_checkpoint";
import { nobleBodyCheckpointSchema } from "../noble_secret_body_checkpoint";
import {
  animalAuthoritySnapshot,
  isAnimalDreamBoard,
} from "../../game/mechanisms/roles/animal_dream/authority";
import {
  fragrantAuthoritySnapshot,
  isFragrantPairBoard,
} from "../../game/mechanisms/roles/fragrant_pair_seer/authority";
import {
  checkpointNobleBodyAuthority,
  isNobleBodyBoard,
} from "../../game/mechanisms/roles/noble_secret_body/authority";
import { getSessionRecorder } from "../recording_context";

export function prepareAnimalCheckpoint(world: World, complete: boolean) {
  const animal = isAnimalDreamBoard(world) ? animalAuthoritySnapshot(world, complete) : null;
  if (isAnimalDreamBoard(world) && !animal) throw Error("animal_checkpoint_unavailable");
  return animal;
}

export function captureAuthorityContributions(
  world: World,
  complete: boolean,
  cursors?: { settlementCount: number; decisionCount: number },
): Pick<
  RecordedCheckpoint,
  | "animalDream"
  | "fragrantPair"
  | "nobleBody"
  | "operationCount"
  | "settlementCount"
  | "decisionCount"
> {
  return {
    ...(isAnimalDreamBoard(world)
      ? { animalDream: animalCheckpointSchema.parse(animalAuthoritySnapshot(world, complete)) }
      : {}),
    ...(isFragrantPairBoard(world)
      ? { fragrantPair: fragrantCheckpointSchema.parse(fragrantAuthoritySnapshot(world, complete)) }
      : {}),
    ...(isNobleBodyBoard(world)
      ? {
          nobleBody: nobleBodyCheckpointSchema.parse(checkpointNobleBodyAuthority(world, complete)),
        }
      : {}),
    ...(isAnimalDreamBoard(world) || isNobleBodyBoard(world) || isFragrantPairBoard(world)
      ? {
          operationCount: getSessionRecorder()?.reproductionOperationCount ?? 0,
          settlementCount:
            cursors?.settlementCount ?? getSessionRecorder()?.reproductionSettlementCount ?? 0,
          decisionCount:
            cursors?.decisionCount ?? getSessionRecorder()?.reproductionDecisionCount ?? 0,
        }
      : {}),
  };
}

/**
 * 负责驱动夜贵族子系统的原 World fixture、有界夜选择、伤害和关闭。输入为脚本步骤、回调与资源请求，输出为原受控轨迹、句柄及边界响应。测试保留字面行动和失败预期；不运行完整对局或传输，也不引入付费模型。
 */
import { createAliveComponent, createCampComponent } from "../../../../../src/game/observation/component-presentation";
import { World } from "../../../../../src/core/domain/world";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { Role, Camp } from "../../../../../src/core/domain/identity";
